parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "category": {
      "type": "string",
      "enum": [
        "support",
        "documents",
        "offers",
        "internal",
        "other"
      ],
      "description": "Exactly one of the five categories, lowercase. If torn between two categories, choose `other`."
    },
    "reason": {
      "type": "string",
      "description": "One sentence explaining which signal made you pick this category. It goes to the system log; the customer never sees it."
    }
  },
  "required": [
    "category",
    "reason"
  ]
}
